import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import {createRequire} from 'node:module';
const require=createRequire(new URL('../runtime/package.json',import.meta.url)),{JSDOM}=require('jsdom');
const code=fs.readFileSync(new URL('../public/document-study/existing-work.js',import.meta.url),'utf8');
const hash='a'.repeat(64),otherHash='b'.repeat(64);
const artifact=(id,kind,name=id)=>({artifactId:id,hash,fileName:name+'.md',relativePath:'Workflow/'+name+'.md',kind});
function data(){return {mode:'existing-work-read-only',stories:[{id:'story-a',name:'Invented Valley',nativeProjectId:'native-a',stage:'Draft checked',step:6,published:'',artifacts:[artifact('a-source','SRC'),artifact('a-research','RESEARCH'),artifact('a-brief','BRIEF'),artifact('a-map','MAP'),artifact('a-part1','DEV','Part one'),artifact('a-part2','DEV','Part two'),artifact('a-check','CHECK'),artifact('a-photo','PHOTO'),artifact('a-carousel','CAROUSEL')],retainedOutputs:[{id:'retained-a',kind:'carousel',slideCount:2,title:'Invented sequence',authority:'retained-bootstrap'}]},{id:'story-b',name:'Invented Valley',stage:'Published record',step:11,published:'https://example.test/story',artifacts:[{...artifact('b-draft','DEV'),hash:otherHash},artifact('b-feedback','FEEDBACK'),{...artifact('b-archive','DEV'),archived:true}]}],sources:[{id:'source-a',title:'Invented source',kind:'note',authority:'Library'}],exclusions:['An excluded invented test fixture'],diagnostics:[]};}
async function setup({enabled=true,catalog=data(),fetchArtifact=null,fetchLibrary=null,dirty=false,media=null,sessions=null,beforeLoad=null,url='http://localhost'}={}){
 const dom=new JSDOM('<div id="app"><main id="workspace"><header class="topbar"></header><nav class="workflowNavigation"></nav><div id="native-editor">Current owner</div></main></div><dialog id="project-library" open><div class="wbf-active"></div></dialog>',{url,runScripts:'outside-only',pretendToBeVisual:true}),w=dom.window,calls=[],mounts=[];
 w.HTMLDialogElement.prototype.showModal=function(){this.open=true;};w.HTMLDialogElement.prototype.close=function(){this.open=false;this.dispatchEvent(new w.Event('close'));};
 w.AR_CREATE_REVIEW_MODE={actualWork:enabled};w.state={project:'native-a',projects:[{id:'native-a',name:'Native title',referenceOnly:false,view:'article',viewedStage:5,blocks:[{id:'human',html:'Invented saved human words'}],slides:[{role:'cover',text:'Invented cover'},{role:'close',text:'Invented ending'}],caption:'Invented caption',history:[]}]};
 const retainedSnapshot=JSON.parse(JSON.stringify({slides:w.state.projects[0].slides,caption:w.state.projects[0].caption}));w.retainedCarouselSnapshot=id=>id==='native-a'?JSON.parse(JSON.stringify(retainedSnapshot)):null;
 w.current=()=>w.state.projects.find(p=>p.id===w.state.project);w.phaseReader=p=>'<section id="native-phase">Native '+p.id+'</section>';
 w.render=()=>{const p=w.current(),ws=w.document.getElementById('workspace');ws.innerHTML='<header class="topbar"></header><nav class="workflowNavigation"></nav>'+(p.referenceOnly?w.phaseReader(p):'<div id="native-editor">Current owner</div>');for(const m of mounts)m();};
 w.switchProject=async id=>{w.state.project=id;w.render();};w.viewPhase=async stage=>{w.current().view='record';w.current().viewedStage=stage;w.render();};
 w.projectLibrary={close:async()=>w.document.getElementById('project-library').close(),open:async()=>{w.document.getElementById('project-library').open=true;}};w.workbenchPieces={open:async()=>{const d=w.document.getElementById('project-library');d.dataset.workbenchPieces='true';d.innerHTML='<div class="wbp-root"><section class="wbp-main"><div>Native piece table</div></section></div>';}};
 w.studyDraft={flush:async()=>({dirty})};w.studyImportedSource={selectSource:async input=>{const response=await w.fetch('/api/source-sessions',{method:'GET',cache:'no-store'}),value=await response.json(),rows=(value.sessions||[]).filter(s=>s.sourceId===input.sourceId);if(rows.length!==1||rows[0].sourceHash!==input.expectedSourceHash||rows[0].version!==input.expectedVersion)throw Error('This conversation changed. Refresh the catalog.');const session=rows[0],host=w.document.createElement('section');host.className='source-reader';host.innerHTML='<h3>'+session.title+'</h3><a data-source-tea-link></a>';host.querySelector('a').href='https://www.teajia.com/admin/compass?'+new URLSearchParams({tab:'library',arSource:session.sourceId});for(const turn of session.turns){const row=w.document.createElement('p');row.dataset.sourceReaderTurn=turn.id;row.textContent=turn.text;host.append(row);}w.document.getElementById('workspace').append(host);return {sessionId:session.id,sourceId:session.sourceId,sourceHash:session.sourceHash,version:session.version};}};w.c3Shell={register:(_n,fn)=>{mounts.push(fn);fn();}};
 w.fetch=async(url,options)=>{calls.push({url,options});if(url==='/api/source-sessions')return {ok:true,json:async()=>sessions||{revision:0,sessions:[]}};if(url==='/api/review/media'&&media)return {ok:true,json:async()=>media};if(url==='/api/review/catalog')return {ok:true,json:async()=>catalog};if(url.startsWith('/api/sources/file?')&&fetchLibrary)return fetchLibrary(url);if(url.startsWith('/api/sources/file?'))return {ok:true,json:async()=>({body:'Invented shared source words'})};if(fetchArtifact)return fetchArtifact(url);return {ok:true,json:async()=>({raw:'Invented record <img src=x onerror=alert(1)>',fileName:'Original.md',provenance:{relativePath:'Workflow/Original.md'}})};};
 beforeLoad?.(w);w.eval(fs.readFileSync(new URL('../public/document-study/display-format.js',import.meta.url),'utf8'));w.eval(code);if(w.existingWork)await w.existingWork.load();await Promise.resolve();return {dom,w,calls};
}
test('disabled mode does not fetch or install another reader',async()=>{const {dom,w,calls}=await setup({enabled:false});assert.equal(w.existingWork,undefined);assert.equal(calls.length,0);dom.window.close();});
test('catalog lists actual identities separately even when titles match and preserves native editor',async()=>{const {dom,w}=await setup();assert.equal(w.document.querySelectorAll('[data-ew-open]').length,2);assert.match(w.document.querySelector('.ew-home').textContent,/Publication recorded/);assert.ok(w.document.getElementById('native-editor'));assert.equal(w.state.projects.length,1);assert.match(w.phaseReader(w.current()),/native-phase/);await w.workbenchPieces.open();assert.equal(w.document.querySelectorAll('.wbp-main .ew-home').length,1);assert.equal(w.document.querySelector('.wbp-main .ew-original-stories').open,false,'the duplicate original inventory must not crowd the Pieces table');assert.match(w.document.querySelector('.wbp-main').textContent,/Native piece table/);dom.window.close();});
test('unknown story opens reference-only with no invented words; all section routes keep exact identity',async()=>{const {dom,w}=await setup();await w.existingWork.openStory('story-b');const p=w.current();assert.equal(p.id,'story-b');assert.equal(p.referenceOnly,true);assert.equal(p.blocks.length,0);assert.equal(p.slides.length,0);for(let stage=1;stage<=12;stage++){await w.viewPhase(stage);assert.equal(w.current(),p);assert.equal(w.document.querySelector('[data-ew-primary]').dataset.ewPrimary,'story-b');}assert.match(w.document.querySelector('.ew-primary').textContent,/Earlier work/);dom.window.close();});
test('known story continues the existing project without forking or replacing human words',async()=>{const {dom,w}=await setup();const p=w.current(),before=JSON.stringify(p.blocks);await w.existingWork.openStory('story-a',{continueWork:true});assert.equal(w.current(),p);assert.equal(w.state.projects.length,1);assert.equal(JSON.stringify(p.blocks),before);assert.equal(p.referenceOnly,false);assert.equal(p.view,'article');assert.ok(w.document.getElementById('native-editor'));await w.viewPhase(3);assert.equal(w.document.querySelectorAll('.ew-context [data-ew-artifact="a-research"]').length,2);assert.equal(w.document.querySelectorAll('.ew-context').length,1);dom.window.close();});
test('stage grouping preserves research, separate parts, media, checks and social output',async()=>{const {dom,w}=await setup(),s=w.existingWork.catalog().stories[0],at=n=>Array.from(w.existingWork.artifactsAt(s,n),a=>a.artifactId);assert.deepEqual(at(3),['a-research','a-brief']);assert.deepEqual(at(4),['a-map']);assert.deepEqual(at(6),['a-part1','a-part2','a-carousel']);assert.deepEqual(at(7),['a-check']);assert.deepEqual(at(8),['a-photo','a-carousel']);assert.deepEqual(at(11),[]);dom.window.close();});
test('Media keeps original record links and counts inside Browser actions across repaint',async()=>{const {dom,w,calls}=await setup();await w.viewPhase(8);const ws=w.document.getElementById('workspace'),browser=w.document.createElement('section');browser.className='wfb-browser k-media';browser.innerHTML='<header class="wfb-thead">Media</header><div class="wfb-ftool"><details class="wfb-tools"><summary>Browser actions</summary><div class="wfb-folder-actions"></div></details></div>';ws.append(browser);w.existingWork.decorate();const history=browser.querySelector('.wfb-folder-actions>.ew-context');assert.ok(history);assert.match(history.querySelector('h3').textContent,/Existing media work · 2/);assert.equal(browser.firstElementChild.tagName,'HEADER','history does not reserve a row above the heading');assert.ok(history.querySelectorAll('[data-ew-artifact="a-photo"]').length>=1);browser.querySelector('.wfb-tools').open=true;history.open=true;history.querySelector('[data-ew-artifact="a-photo"]').click();await new Promise(resolve=>setTimeout(resolve,0));assert.ok(calls.some(c=>c.url==='/api/review/artifact?id=a-photo&hash='+hash));browser.innerHTML='<header class="wfb-thead">Media</header><div class="wfb-ftool"><details class="wfb-tools"><summary>Browser actions</summary><div class="wfb-folder-actions"></div></details></div>';w.existingWork.placeMediaHistory();assert.ok(browser.querySelector('.wfb-folder-actions>.ew-context [data-ew-artifact="a-photo"]'),'repaint restores the original entrance');browser.innerHTML='<header class="wfb-thead">Photo preview</header>';w.existingWork.placeMediaHistory();assert.equal(browser.querySelector('.ew-context'),null,'preview leaves the historical entrance in Browser actions');assert.ok(ws.querySelector(':scope>.ew-context [data-ew-artifact="a-photo"]'));dom.window.close();});
test('Research keeps its original history inside the maintained tools after repeated existing-work decoration',async()=>{const {dom,w}=await setup();await w.viewPhase(3);const ws=w.document.getElementById('workspace'),history=ws.querySelector('.ew-context'),tools=w.document.createElement('details');tools.className='wb-research-tools';ws.append(tools);tools.append(history);let mutations=0;const observer=new w.MutationObserver(rows=>{mutations+=rows.length});observer.observe(ws,{childList:true,subtree:true});for(let i=0;i<6;i++)w.existingWork.decorate();await new Promise(resolve=>setTimeout(resolve,0));observer.disconnect();assert.strictEqual(history.parentElement,tools,'Research owns the history entrance within its source tools');assert.equal(mutations,0,'repeated decoration must not move the same record back and forth');assert.ok(history.querySelector('[data-ew-artifact="a-research"]'));dom.window.close();});
test('reader binds artifact to story and exact hash, escapes text, clears raw on close and never persists it',async()=>{const {dom,w,calls}=await setup();await assert.rejects(w.existingWork.openArtifact('story-b','a-source'),/unavailable/);await w.existingWork.openArtifact('story-a','a-source');const d=w.document.getElementById('ew-reader');assert.match(d.querySelector('pre').textContent,/<img/);assert.equal(d.querySelector('img'),null);assert.match(calls.at(-1).url,new RegExp('hash='+hash));assert.ok(calls.every(c=>c.options.method==='GET'));assert.equal(w.localStorage.length,0);d.close();assert.equal(d.querySelector('.ew-read-body').textContent,'');dom.window.close();});
test('late original read cannot populate a changed project',async()=>{let resolve;const pending=new Promise(r=>resolve=r);const {dom,w}=await setup({fetchArtifact:()=>pending});const read=w.existingWork.openArtifact('story-a','a-source');w.state.projects.push(w.existingWork.referenceModel(w.existingWork.catalog().stories[1]));w.state.project='story-b';resolve({ok:true,json:async()=>({raw:'Stale invented original'})});await read;assert.equal(w.document.querySelector('.ew-read-body').textContent,'');dom.window.close();});
test('dirty current words block story switching without adding a reference or changing native state',async()=>{const {dom,w}=await setup({dirty:true});await assert.rejects(w.existingWork.openStory('story-b'),/Save or resolve/);assert.equal(w.current().id,'native-a');assert.equal(w.state.projects.length,1);dom.window.close();});
test('retained carousel reads existing words without selecting an editor, approving or importing',async()=>{const {dom,w,calls}=await setup();const p=w.current(),before=JSON.stringify(p);w.existingWork.openRetained('story-a','retained-a');const d=w.document.getElementById('ew-reader');assert.match(d.textContent,/Invented cover/);assert.match(d.textContent,/Invented caption/);assert.equal(d.querySelector('[contenteditable],input,textarea'),null);assert.equal(JSON.stringify(p),before);assert.equal(calls.length,1);dom.window.close();});
test('repeated mounts and external Pieces repaints do not duplicate the catalog',async()=>{const {dom,w}=await setup();for(let i=0;i<20;i++)w.existingWork.decorate();assert.equal(w.document.querySelectorAll('.ew-home').length,1);await w.workbenchPieces.open();const host=w.document.querySelector('.wbp-main');host.replaceChildren(w.document.createElement('div'));await new Promise(resolve=>w.setTimeout(resolve,0));assert.equal(host.querySelectorAll('.ew-home').length,1);dom.window.close();});
test('Library shows all actual authorities with search, preserves folder owner and reads its maintained source API',async()=>{const catalog=data();catalog.sources=[{id:'lib-one',title:'Invented shared learning',kind:'note',authority:'library'},{id:'mag-one',title:'Invented research',kind:'RESEARCH',authority:'magazine-original',artifactId:'record-one',hash}];const {dom,w,calls}=await setup({catalog});await w.viewPhase(1);const ws=w.document.getElementById('workspace'),old=w.document.createElement('section');old.className='wfb-browser k-library';old.innerHTML='<button>Original owner handler</button>';const handler=()=>{};old.querySelector('button').onclick=handler;ws.append(old);w.existingWork.decorate();assert.equal(ws.querySelector('.ew-source-library .ew-source-results').children.length,2);assert.equal(old.style.getPropertyValue('display'),'none');assert.equal(old.querySelector('button').onclick,handler);const search=ws.querySelector('[data-ew-source-search]');search.value='research';search.dispatchEvent(new w.Event('input',{bubbles:true}));assert.equal(ws.querySelector('.ew-source-results').children.length,1);assert.match(ws.querySelector('.ew-source-results').textContent,/Invented research/);const select=ws.querySelector('[data-ew-authority]');assert.match(select.textContent,/magazine-original · 1/);await w.existingWork.openSource('lib-one');assert.equal(calls.at(-1).url,'/api/sources/file?id=lib-one');assert.equal(w.document.querySelector('.ew-read-body pre').textContent,'Invented shared source words');await w.viewPhase(2);assert.equal(old.style.getPropertyValue('display'),'');assert.equal(w.localStorage.length,0);dom.window.close();});
test('reference-only initial state opens safely without a synthetic template project',async()=>{const {dom,w}=await setup();w.state.projects=[];w.state.project=null;await w.existingWork.openStory('story-b');assert.equal(w.current().id,'story-b');assert.equal(w.current().referenceOnly,true);assert.equal(w.current().blocks.length,0);dom.window.close();});
test('actual Magazine precedes Bench resume and demotes duplicate inventory and empty output moves without replacing handlers',async()=>{const {dom,w}=await setup();const d=w.document.getElementById('project-library'),main=w.document.createElement('main');main.className='ht-home-main';main.innerHTML='<section class="wbf-bench"><div class="wbf-bench-story"><button data-resume>Resume native owner</button><section><div data-wbf-next-list><ol></ol><button data-wbf-next-refresh>Refresh</button></div></section></div><section class="wbf-active"><button data-pl-open="native-a">Original project</button></section></section>';d.append(main);const resume=main.querySelector('[data-resume]'),handler=()=>{};resume.onclick=handler;w.existingWork.decorate();assert.equal(main.firstElementChild.className,'ew-home');assert.ok(main.querySelector('.ew-other-projects .wbf-active'));assert.ok(main.querySelector('.ew-saved-moves [data-wbf-next-refresh]'));assert.equal(main.querySelector('[data-resume]'),resume);assert.equal(resume.onclick,handler);for(let i=0;i<10;i++)w.existingWork.decorate();await new Promise(r=>w.setTimeout(r,0));assert.equal(d.querySelectorAll('.ew-home').length,1);assert.equal(main.querySelectorAll('.ew-other-projects').length,1);assert.equal(d.querySelectorAll('.ew-saved-moves').length,1);dom.window.close();});
test('only explicitly excluded cached fixture projects are quarantined exactly; unknown human projects and original cache survive',async()=>{const catalog=data(),{dom,w}=await setup({catalog});const sample={id:'fixture-sample',name:'Invented sample',blocks:[{id:'sample-block',html:'Invented cached sample words'}],history:[{label:'Retained sample history'}]},unknown={id:'human-unlisted',name:'Unlisted human project',blocks:[{id:'human-block',html:'Invented human draft'}]};w.state.projects.push(sample,unknown);w.state.project=sample.id;w.localStorage.setItem('original-cache',JSON.stringify(sample));const original=w.localStorage.getItem('original-cache');catalog.excludedProjectIds=['fixture-sample'];await w.existingWork.load();assert.equal(w.existingWork.quarantinedProjects()[0],sample);assert.equal(sample.blocks[0].html,'Invented cached sample words');assert.equal(w.localStorage.getItem('original-cache'),original);assert.ok(w.state.projects.includes(unknown));assert.ok(!w.state.projects.includes(sample));assert.equal(w.current().id,'native-a');assert.equal(w.state.projects.length,2);catalog.excludedProjectIds=[];await w.existingWork.load();assert.ok(w.state.projects.includes(sample));assert.equal(w.existingWork.quarantinedProjects().length,0);dom.window.close();});
test('native article Read context uses Read records while preserving document geometry and owner nodes',async()=>{const {dom,w}=await setup();const p=w.current();p.view='article';p.viewedStage=6;w.render();const editor=w.document.getElementById('native-editor');assert.equal(w.existingWork.contextStage(p),6);assert.match(w.document.querySelector('.ew-context>h3').textContent,/Existing read work/);assert.equal(w.document.querySelector('.ew-context').querySelector('[data-ew-artifact="a-map"]')!==null,true);assert.equal(w.document.getElementById('native-editor'),editor);p.viewedStage=5;p.readonly=true;assert.equal(w.existingWork.contextStage(p),6);dom.window.close();});
test('existing safe prose renderer presents body while exact hashed original remains available separately',async()=>{const raw='---\ntitle: Invented metadata\n---\n\n# Invented research\n\nInvented evidence.',{dom,w}=await setup({fetchArtifact:async()=>({ok:true,json:async()=>({raw,provenance:{relativePath:'Workflow/Invented.md'}})})});const inputs=[];w.studyStageProse={render:body=>{inputs.push(body);return '<p>Existing trusted prose rendering</p>';}};await w.existingWork.openArtifact('story-a','a-research');assert.equal(inputs.length,1);assert.ok(!inputs[0].includes('title:'));assert.match(inputs[0],/# Invented research/);const d=w.document.getElementById('ew-reader');assert.equal(d.querySelector('.ew-prose').textContent,'Existing trusted prose rendering');assert.equal(d.querySelector('.ew-original-text pre').textContent,raw);assert.equal(d.querySelector('.ew-original-text').open,false);assert.equal(w.localStorage.length,0);dom.window.close();});

test('late asynchronous project recovery keeps confirmed fixtures quarantined without deleting their object',async()=>{const catalog=data();catalog.excludedProjectIds=['fixture-late'];const{dom,w}=await setup({catalog});const sample={id:'fixture-late',name:'Invented recovered test',blocks:[{id:'keep',html:'Invented words retained'}]};w.state.projects.push(sample);w.existingWork.decorate();assert.ok(!w.state.projects.includes(sample));assert.ok(w.existingWork.quarantinedProjects().includes(sample));assert.equal(sample.blocks[0].html,'Invented words retained');dom.window.close();});
test('retained design uses the maintained slide renderer without importing or changing its existing words',async()=>{const{dom,w}=await setup();const p=w.current(),before=JSON.stringify(p.slides),calls=[];w.renderSlide=s=>{calls.push(s);return '<div class="invented-render">'+s.text+'</div>';};w.existingWork.openRetained('story-a','retained-a',{look:true});assert.equal(w.document.querySelectorAll('#ew-reader .donorFrame').length,2);assert.deepEqual(JSON.parse(JSON.stringify(calls[0])),JSON.parse(JSON.stringify(p.slides[0])));assert.equal(JSON.stringify(p.slides),before);assert.match(w.document.querySelector('#ew-reader .ew-read-status').textContent,/not an approval/i);dom.window.close();});

test('retained guidance and unassigned files use exact existing hash readers; published links require https',async()=>{const catalog=data();catalog.guidance=[artifact('guide-one','GUIDE')];catalog.unassigned=[artifact('archive-one','DEV')];catalog.stories[0].publishedUrl='javascript:alert(1)';catalog.stories[1].publishedUrl='https://example.test/published';const{dom,w,calls}=await setup({catalog});assert.equal(w.document.querySelectorAll('[data-ew-global-artifact]').length,2);assert.equal(w.document.querySelectorAll('.ew-publication').length,1);assert.equal(w.document.querySelector('.ew-publication').href,'https://example.test/published');await w.existingWork.openArtifact(null,'guide-one',{global:true});assert.match(calls.at(-1).url,/id=guide-one&hash=/);await assert.rejects(w.existingWork.openArtifact(null,'a-part1',{global:true}),/unavailable/);assert.equal(w.localStorage.length,0);dom.window.close();});
test('saved workspace records retain independent identity and explain unverified manuscript matching',async()=>{const catalog=data();catalog.workspacePieces=[{id:'uuid-a',title:'Invented Valley',wordCount:4},{id:'uuid-b',title:'Invented Valley',wordCount:7}];const{dom,w,calls}=await setup({catalog});assert.equal(w.document.querySelectorAll('[data-ew-workspace]').length,2);const before=JSON.stringify(w.state.projects);w.existingWork.openWorkspace('uuid-b');assert.match(w.document.querySelector('.ew-read-status').textContent,/not verified/);assert.match(w.document.querySelector('.ew-read-body pre').textContent,/uuid-b/);assert.equal(JSON.stringify(w.state.projects),before);assert.equal(calls.length,1);dom.window.close();});

test('Media browses name-matched folder originals with guarded read URLs and preserves browser words',async()=>{const media={items:[{id:'media-a',storyFolder:'Invented Valley',fileName:'Original.jpg',kind:'photo',contentType:'image/jpeg',revision:hash,openable:true},{id:'media-other',storyFolder:'Other Valley',fileName:'Other.jpg',kind:'photo',revision:hash,openable:true}],coverage:{truncated:false}}, {dom,w}=await setup({media});const p=w.current(),before=JSON.stringify(p);await w.viewPhase(8);await w.existingWork.loadMedia();assert.equal(w.document.querySelectorAll('.ew-media-card').length,1);w.existingWork.openMedia('media-a');assert.match(w.document.querySelector('.ew-original-media').src,/id=media-a&revision=/);assert.throws(()=>w.existingWork.openMedia('media-other'),/not available/);assert.equal(JSON.stringify(p),before.replace('"view":"article"','"view":"record"').replace('"viewedStage":5','"viewedStage":8'));assert.equal(w.localStorage.length,0);dom.window.close();});

test('browser image occurrences preserve exact block and occurrence independently of folder browsing',async()=>{const{dom,w}=await setup({media:{items:[],coverage:{truncated:false}}});const p=w.current();p.blocks=[{id:'exact-block',html:'<figure><img src="/document-study/assets/photos/invented.jpg"><figcaption>Invented caption</figcaption></figure>'},{id:'second-use',html:'<img src="/document-study/assets/photos/invented.jpg">'},{id:'remote',html:'<img src="https://example.test/private.jpg">'}];const before=JSON.stringify(p.blocks);await w.viewPhase(8);await w.existingWork.loadMedia();const placements=w.existingWork.savedPlacements(p);assert.equal(placements.length,2);assert.notEqual(placements[0].id,placements[1].id);assert.equal(w.document.querySelectorAll('[data-ew-placement]').length,2);w.existingWork.openPlacement(placements[0].id);assert.match(w.document.querySelector('.ew-read-body details').textContent,/exact-block/);assert.match(w.document.querySelector('.ew-read-body').textContent,/Invented caption/);assert.equal(JSON.stringify(p.blocks),before);dom.window.close();});

test('retained conversation links from exact Library source identity and reads unchanged speaker turns safely',async()=>{const catalog=data();catalog.conversations=[{id:'session-one',title:'Invented conversation',sourceId:'library-one',sourceHash:hash,version:2,turnCount:1}];catalog.sources=[{id:'library-one',title:'Invented transcript',authority:'library'}];const sessions={sessions:[{id:'session-one',sourceId:'library-one',sourceHash:hash,version:2,turns:[{id:'turn-a',speaker:'Invented speaker',text:'Exact invented <img> words'}]}]};const{dom,w,calls}=await setup({catalog,sessions});assert.match(w.document.querySelector('.ew-home').textContent,/Retained conversations/);await w.viewPhase(1);assert.equal(w.document.querySelectorAll('.ew-source-library a[data-ew-source="library-one"]').length,1);await w.existingWork.openConversation('session-one');assert.equal(w.document.querySelector('[data-source-reader-turn]').dataset.sourceReaderTurn,'turn-a');assert.equal(w.document.querySelector('[data-source-reader-turn]').textContent,'Exact invented <img> words');assert.equal(w.document.querySelector('.source-reader img'),null);assert.equal(w.document.querySelector('#ew-reader'),null);assert.equal(calls.at(-1).url,'/api/source-sessions');assert.equal(w.localStorage.length,0);dom.window.close();});
test('changed retained source version refuses conversation rendering instead of silently refreshing guards',async()=>{const catalog=data();catalog.conversations=[{id:'session-one',title:'Invented',sourceId:'library-one',sourceHash:hash,version:1}];const{dom,w}=await setup({catalog,sessions:{sessions:[{id:'session-one',sourceId:'library-one',sourceHash:otherHash,version:2,turns:[{text:'New words'}]}]}});await assert.rejects(w.existingWork.openConversation('session-one'),/changed/);assert.equal(w.document.querySelector('#ew-reader'),null);dom.window.close();});

test('verified workspace pickup selects exact existing binding and leaves an unresolved record without a fake target',async()=>{const catalog=data();catalog.workspacePieces=[{id:'piece-a',documentId:'doc-a',title:'Invented'}];catalog.workspaceLinks={pieces:[{workspaceId:'piece-a',targets:[{workspaceId:'piece-a',documentId:'doc-a',parentStudyId:'native-a',rootBindingId:'exact-binding',partKey:'2'}]}]};const{dom,w,calls}=await setup({catalog,fetchArtifact:async url=>({ok:true,json:async()=>({binding:{id:'exact-binding',parentStudyId:'native-a',title:'Invented part2'},raw:'Exact saved part2 words',expected:{workflow:{draft:hash}}})})});const before=JSON.stringify(w.current().blocks);await w.existingWork.openWorkspaceTarget('piece-a',0);assert.match(calls.at(-1).url,/bindingId=exact-binding&parentStudyId=native-a/);assert.match(w.document.querySelector('.ew-read-body').textContent,/Exact saved part2 words/);assert.equal(w.current().viewedStage,6);assert.equal(JSON.stringify(w.current().blocks),before);await assert.rejects(w.existingWork.openWorkspaceTarget('missing',0),/unavailable/);dom.window.close();});
test('tea library handoff contains only verified transcript sourceUUID and never sends text or credentials',async()=>{const id='11111111-1111-4111-8111-111111111111',catalog=data();catalog.sources=[{id,title:'Invented transcript',authority:'library'}];catalog.conversations=[{id:'session-one',sourceId:id,sourceHash:hash,version:1,title:'Invented'}];const{dom,w,calls}=await setup({catalog,sessions:{sessions:[{id:'session-one',sourceId:id,sourceHash:hash,version:1,turns:[{speaker:'Invented',text:'Private invented text'}]}]}});await w.existingWork.openConversation('session-one');const link=w.document.querySelector('[data-source-tea-link]'),url=new URL(link.href);assert.equal(url.origin,'https://www.teajia.com');assert.deepEqual([...url.searchParams.keys()],['tab','arSource']);assert.equal(url.searchParams.get('arSource'),id);assert.equal(link.href.startsWith('https://www.teajia.com/'),true);assert.ok(!link.href.includes('Private'));assert.ok(calls.every(c=>!c.url.startsWith('http')));assert.equal(w.document.querySelector('#ew-reader'),null);await w.existingWork.openArtifact('story-a','a-source');assert.equal(w.document.querySelector('.ew-tea-link'),null);dom.window.close();});

test('direct transcript URL opens only the exact Library UUID, preserves selection and does not repeat on refresh',async()=>{const id='11111111-1111-4111-8111-111111111111',catalog=data();catalog.sources=[{id,title:'Invented transcript',authority:'library'}];catalog.conversations=[{id:'session-one',sourceId:id,sourceHash:hash,version:1,title:'Invented conversation'}];const{dom,w,calls}=await setup({url:'http://localhost/document-study/index.html?reviewSource='+id,catalog,sessions:{sessions:[{id:'session-one',sourceId:id,sourceHash:hash,version:1,turns:[{id:'turn-a',text:'Exact invented full transcript'}]}]}});assert.equal(w.current().id,'native-a');assert.match(w.document.querySelector('.source-reader').textContent,/Exact invented full transcript/);assert.equal(w.document.querySelectorAll('[data-source-tea-link]').length,1);const count=calls.filter(c=>c.url==='/api/source-sessions').length;await w.existingWork.load();assert.equal(calls.filter(c=>c.url==='/api/source-sessions').length,count);assert.equal(w.document.querySelector('#ew-reader'),null);assert.equal(w.localStorage.length,0);dom.window.close();});
