function workspaceData({collection=false}={}){const catalog=data();catalog.workspacePieces=[{id:'pickup-piece',documentId:'pickup-document',title:'Exact saved work'}];catalog.workspaceLinks={pieces:[{workspaceId:'pickup-piece',targets:[{workspaceId:'pickup-piece',documentId:'pickup-document',parentStudyId:'native-a',rootBindingId:'pickup-binding',partKey:collection?'collection':'2'}]}]};return catalog;}
function nativePickup(w,{collection=false}={}){w.AR_CREATE_REVIEW_MODE.studyDraftCorrections=true;if(collection){w.current().collectionKind='collection-root';w.current().collectionBindingId='pickup-binding';}w.pickups=[];w.stageCalls=[];const phase=w.viewPhase;w.viewPhase=async n=>{w.stageCalls.push(n);await phase(n);};w.studyDraft.openBinding=async input=>{w.pickups.push({...input});w.current().view='article';w.current().viewedStage=5;return {bindingId:input.bindingId,parentStudyId:input.parentStudyId,expected:{workflow:{draft:hash}},dirty:false};};w.c3WorkbenchFrame={openTool:async name=>{w.checkedTool=name;}};}
function nativeCarouselBeforePrimary(w){
 nativePickup(w);let selected=true;w.primaryClears=[];w.carouselReroutes=[];w.studyOutputConnection={selection:()=>selected?{projectId:'native-a',rootBindingId:'old-carousel-root',output:{id:'saved-native-eight',kind:'carousel'},owner:{kind:'carousel-words'}}:null,flush:async()=>{},clearSelection:async input=>{w.primaryClears.push({...input});assert.equal(w.pickups.at(-1)?.bindingId,input.rootBindingId);selected=false;}};
 w.realOutputOverview={read:async()=>({projectId:'native-a',outputs:[{id:'saved-native-eight',format:'Carousel',rootBindingId:'old-carousel-root'}]}),onAction:async input=>{w.carouselReroutes.push(input);w.current().view='record';w.current().viewedStage=9;}};
 w.eval(fs.readFileSync(new URL('../public/document-study/workspace-navigation.js',import.meta.url),'utf8'));
}
const workspaceURL=stage=>'http://localhost/document-study/index.html?'+new URLSearchParams({reviewStory:'story-a',reviewWorkspace:'pickup-piece',reviewBinding:'pickup-binding',reviewStage:String(stage)});
