async function authorDecisionFixture({foreignArticle=false,foreignCarousel=false,chosen=false}={}){
 const {approvalMarks}=await import('../runtime/src/workspaces/editorial-state.mjs');const raw='One ==waiting phrase==.\n\nTwo ==other waiting words==.\n\n%% private note with ==not a decision== %%';let reads=0;const f=await setup({catalog:magazineData(),beforeLoad:w=>magazineOwner(w),fetchArtifact:async url=>{if(!url.startsWith('/api/magazine/working-draft/read?'))throw Error('Unexpected read');reads++;return {ok:true,json:async()=>({authority:{kind:'magazine',storyId:'registered-valley-independent',pieceId:foreignArticle?'foreign':'registered-piece-1'},document:{text:raw,hash},projection:[]})};}});f.w.ArStudyOutputHost={approvalMarks};f.w.directionChoiceContext={read:async parentStudyId=>({available:true,parentStudyId,hash:otherHash,revision:3,selectedAngle:chosen?{text:'Chosen invented angle'}:null,selectedTitle:null})};const tuple={kind:'carousel-words',projectId:'physical-project',documentId:'physical-document',outputId:'carousel'},proof={...tuple,wordsHash:'c'.repeat(64),expected:{projectId:tuple.projectId,documentId:foreignCarousel?'foreign':tuple.documentId,outputId:tuple.outputId,markdownHash:'d'.repeat(64)}};let lists=0;f.w.workbenchPieces={listForProject:async projectId=>{lists++;return {projectId,pieces:[{reference:'exact-carousel',editionRole:'current',format:'Carousel',kind:'workspace-reference'}],errors:[]};},readPreviewReference:async()=>({kind:'native',identity:{projectId:'native-a'},read:{output:{id:'carousel',kind:'carousel',stage:'words',slides:[{id:'one'},{id:'two'},{id:'three'}]},wordOwner:tuple,writingProof:proof}})};return {...f,reads:()=>reads,lists:()=>lists};
}
test('Home author decisions read the canonical Article, bound choices and exact current Carousel without activating any writer',async()=>{const f=await authorDecisionFixture();try{const before=JSON.stringify(f.w.current()),[a,b]=await Promise.all([f.w.existingWork.readAuthorDecisions(),f.w.existingWork.readAuthorDecisions()]);assert.equal(a.state,'ready');assert.deepEqual(JSON.parse(JSON.stringify(a)),JSON.parse(JSON.stringify(b)));assert.equal(a.items.find(item=>item.kind==='passages').count,2,'existing parser counts actual marks, not a fixed ten or protected notes');assert.equal(a.items.find(item=>item.kind==='carousel-words').count,3,'slide count comes from this exact saved Carousel, not one pending decision');assert.deepEqual(Array.from(a.items,item=>item.kind).sort(),['angle','carousel-words','passages','title']);assert.equal(f.reads(),1);assert.equal(f.lists(),1);assert.equal(f.w.magazineOpens.length,0);assert.equal(JSON.stringify(f.w.current()),before);assert.ok(f.calls.every(call=>call.options.method==='GET'));f.w.dispatchEvent(new f.w.Event('study-direction-choice-change'));await f.w.existingWork.readAuthorDecisions();assert.equal(f.reads(),2);}finally{f.dom.window.close();}});
